  if(!CTX_STATIC_P)CTX_STATIC_P=fetch("contexto.json").then(r=>r.ok?r.json():{})
    .catch(()=>({})).then(j=>{CTX_ESTATICO=j||{};return CTX_ESTATICO;});
  return CTX_STATIC_P;
}
function ctxStatic(q){
  const k=String(q||"").trim().slice(0,400);if(!k)return null;
  const v=CTX_ESTATICO[k];if(v==null)return null;
  return typeof v==="string"?{txt:v||null,ok:true}:{txt:v.txt||null,ok:v.ok!==false};
}
function ctxLS(q){
  const k=String(q||"").trim().slice(0,400);if(!k)return null;
  try{
    const v=JSON.parse(localStorage.getItem(CTX_LS)||"{}")[k];
    if(v&&Date.now()-(v.t||0)<CTX_TTL)return {txt:v.txt||null,ok:v.ok!==false};
